using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

// --- Configuration -----------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Tools -------------------------------------------------------------------

var notebook = new Notebook();

IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    instructions: """
        You are a research assistant. When given a topic, follow these steps:
        1. Use the web_search tool to find relevant information. Search multiple
           queries to get broad coverage — at least 2-3 different searches.
        2. Use the add_note tool to save each important finding with its source URL.
        3. After gathering enough information, use the get_notes tool to review
           all your notes, then provide a clear, well-structured summary with
           source citations.
        Be thorough but concise. Always cite your sources.
        """,
    tools: [
        AIFunctionFactory.Create(WebSearchTool.SearchAsync, "web_search",
            "Search the web for information on a query. Returns a list of result titles, snippets, and URLs."),
        AIFunctionFactory.Create(notebook.AddNote, "add_note",
            "Save a research note with its source URL for later reference."),
        AIFunctionFactory.Create(notebook.GetNotes, "get_notes",
            "Retrieve all saved research notes."),
    ]);

// --- Main loop ---------------------------------------------------------------

Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent (MAF)           ║");
Console.WriteLine("╠══════════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or 'quit'.  ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
    {
        break;
    }

    notebook.Clear();

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Researching… (the agent will search the web and compile notes)\n");
    Console.ResetColor();

    try
    {
        var runOptions = new ChatClientAgentRunOptions(new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 4096,
        });

        await foreach (var update in agent.RunStreamingAsync(
            $"Research the following topic and provide a comprehensive summary: {topic}",
            options: runOptions))
        {
            Console.Write(update.Text);
        }

        Console.WriteLine("\n");
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }
}

Console.WriteLine("Goodbye!");

// =============================================================================
// Web Search Tool — uses the Brave Search API if a key is provided, otherwise
// falls back to a DuckDuckGo HTML scrape for zero-config demos.
// =============================================================================

static class WebSearchTool
{
    private static readonly HttpClient s_http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
    };

    public static async Task<IList<SearchResult>> SearchAsync(
        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (default 5)")] int maxResults = 5)
    {
        var braveKey = Environment.GetEnvironmentVariable("BRAVE_SEARCH_API_KEY");

        return braveKey is not null
            ? await BraveSearchAsync(query, maxResults, braveKey)
            : await DuckDuckGoFallbackAsync(query, maxResults);
    }

    private static async Task<IList<SearchResult>> BraveSearchAsync(
        string query, int maxResults, string apiKey)
    {
        var url = $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count={maxResults}";
        using var request = new HttpRequestMessage(HttpMethod.Get, url);
        request.Headers.Add("X-Subscription-Token", apiKey);
        request.Headers.Add("Accept", "application/json");

        using var response = await s_http.SendAsync(request);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(await response.Content.ReadAsStreamAsync());
        var results = new List<SearchResult>();

        if (doc.RootElement.TryGetProperty("web", out var web) &&
            web.TryGetProperty("results", out var items))
        {
            foreach (var item in items.EnumerateArray().Take(maxResults))
            {
                results.Add(new SearchResult(
                    item.GetProperty("title").GetString() ?? "",
                    item.GetProperty("description").GetString() ?? "",
                    item.GetProperty("url").GetString() ?? ""));
            }
        }

        return results;
    }

    private static async Task<IList<SearchResult>> DuckDuckGoFallbackAsync(
        string query, int maxResults)
    {
        // DuckDuckGo Instant Answer API (JSON, no key required).
        var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1";
        using var response = await s_http.GetAsync(url);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(await response.Content.ReadAsStreamAsync());
        var results = new List<SearchResult>();

        // Abstract text (main result)
        var abstractText = doc.RootElement.GetProperty("AbstractText").GetString();
        var abstractUrl = doc.RootElement.GetProperty("AbstractURL").GetString();
        var abstractSource = doc.RootElement.GetProperty("AbstractSource").GetString();
        if (!string.IsNullOrWhiteSpace(abstractText))
        {
            results.Add(new SearchResult(abstractSource ?? "Summary", abstractText, abstractUrl ?? ""));
        }

        // Related topics
        if (doc.RootElement.TryGetProperty("RelatedTopics", out var topics))
        {
            foreach (var topic in topics.EnumerateArray().Take(maxResults - results.Count))
            {
                if (topic.TryGetProperty("Text", out var text) &&
                    topic.TryGetProperty("FirstURL", out var topicUrl))
                {
                    results.Add(new SearchResult(
                        text.GetString()?[..Math.Min(text.GetString()!.Length, 80)] ?? "",
                        text.GetString() ?? "",
                        topicUrl.GetString() ?? ""));
                }
            }
        }

        if (results.Count == 0)
        {
            results.Add(new SearchResult(
                "No results", $"No instant answers found for '{query}'. Try a different query.", ""));
        }

        return results;
    }
}

