// Notebook Tool — simple in-memory note store
// =============================================================================

class Notebook
{
    private readonly List<Note> _notes = [];

    [Description("Save a research finding for later reference")]
    public string AddNote(
        [Description("The content of the research note")] string content,
        [Description("The source URL where this information was found")] string sourceUrl)
    {
        _notes.Add(new Note(content, sourceUrl, DateTime.UtcNow));
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Get all saved research notes")]
    public IReadOnlyList<Note> GetNotes()
    {
        return _notes.AsReadOnly();
    }

    public void Clear() => _notes.Clear();
}

